from common import *
import csv,collections

def count_registry(path):
 out=collections.defaultdict(collections.Counter)
 for r in csv.DictReader(Path(path).open(encoding='utf-8')):
  if r['usable_as_content_evidence']=='True':out[r['subject']][r['class']]+=1
 return out

def report():
 before=count_registry(ROOT/'audit/outputs/registry-before.csv');after=count_registry(ROOT/'registry/papers.csv');subjects=sorted(set(before)|set(after)|{'tieng-nga','tieng-nhat','tieng-han','tieng-trung'})
 missing={'sinh-hoc':'Chính thức 2025: trang 1, câu 1–10','lich-su':'Chính thức 2025: trang 1, câu 1–10','gdktpl':'Chính thức 2025: trang 1, câu 1–8','vat-li':'Chính thức 2026: trang 4','tieng-han':'Mã 1725: trang 3 và 4; ảnh mạng xã hội chỉ là trang 1 mã 1727','tieng-nhat':'Mã 1628: trang 4; ưu tiên mã đầy đủ, không trộn các mã','tieng-trung':'Chưa có đề thật; khóa không thay được đề'}
 stage1qa=load(ROOT/'audit/outputs/stage1-qa.json') if (ROOT/'audit/outputs/stage1-qa.json').exists() else []
 ranking=load(ROOT/'audit/outputs/prototype-ranking.json') if (ROOT/'audit/outputs/prototype-ranking.json').exists() else []
 new=load(ROOT/'audit/outputs/new-prototypes.json') if (ROOT/'audit/outputs/new-prototypes.json').exists() else {}
 stops=sorted(p for p in (ROOT/'audit/outputs/stops').glob('*.json') if not load(p).get('resolved_by_latest_attempt'))
 profile_subjects=[p.parent.name for p in (ROOT/'profiles').glob('*/profile.compact.json')] if (ROOT/'profiles').exists() else []
 lines=['# Báo cáo dữ liệu đề Lecturing — 2026-11-02','','## Kết luận trong năm dòng','',f'Đã cập nhật phiên âm và sổ dữ liệu; {len(stage1qa)} bản mới đi qua QA tự động, trạng thái từng bản được giữ rõ.',f'Đã có hồ sơ compact cho {len(profile_subjects)} môn; số liệu đề chính thức và đề tỉnh được tách riêng.','Ma trận chỉ được audit/đề xuất trong corpus; Toán đặt tay vẫn chờ chủ app quyết định.',f'Đã kiểm {len(ranking)} bản prototype phân biệt; mọi nghi vấn khóa/khoa học/lịch sử vẫn cần giáo viên.' if ranking else 'Chưa có kết quả chấm prototype hợp lệ; không ghi phần chưa kiểm thành số không.',f'Có {len(stops)} bước dừng được lưu; trạng thái mẫu ngoại ngữ và giới hạn ở dưới. Không merge hoặc push.','','## Dữ liệu trước và sau','','Cờ dùng được là phiên âm đủ cho phân tích nội bộ, không phải giáo viên chấp thuận. Đề chính thức từ bản chụp/bên thứ ba vẫn có rủi ro nguồn. Một đề có nhiều mã hoán vị không tính nhiều lần.','', '| Môn | Chính thức trước → sau | Tỉnh trước → sau | Trang/nguồn chủ app cần tìm |','|---|---:|---:|---|']
 for s in subjects:lines.append(f'| {s} | {before[s]["official"]} → {after[s]["official"]} | {before[s]["provincial_third_party"]} → {after[s]["provincial_third_party"]} | {missing.get(s,"Xem STATUS từng đề; không suy ra đủ từ số file tải.")} |')
 lines+=['','Sử/Sinh chính thức 2026 đã đủ bốn trang trước đợt này; không nhầm với các bản 2025 thiếu trang. Toán/Vật lí/Hóa 2025 chọn một mã đầy đủ, không cộng hai mã hoán vị thành hai đề độc lập. Danh sách chọn/bỏ và lý do: '+str(ROOT/'audit/outputs/selection.json'),'', '## Ma trận mặc định','','Chi tiết từng phần và các chủ đề thiếu/lệch trọng số: '+str(ROOT/'audit/default-matrices.md'), 'Đề xuất theo `_PART_TOPICS`, có số đề bằng chứng từng chủ đề: '+str(ROOT/'audit/proposed-matrices.json'), '', 'Các quyết định cần xem riêng: Toán phần III xác suất; Sinh tỷ trọng di truyền và các dạng sinh lý/điều hoà; Sử lớp mười và mười một. Chỉ gọi một nội dung thiếu khi ánh xạ chương xác nhận nó nằm ngoài chương mặc định; không dựa vào từ khóa đơn lẻ. Một đề chính thức không đủ để kết luận tần suất dài hạn.','', '## Prototype và phương án nhiễu','','Thứ tự ưu tiên rà trước, không phải thang điểm so năng lực giữa các môn. Dùng khóa công bố để tính chiều dài; tự giải trước khi so khóa. Bất đồng model không tự chứng minh khóa sai. Các bản corpus/product trùng byte chỉ chấm một lần.','', '| Môn | Mã mù | Bất đồng khóa cần rà | Cờ nội dung | Nhiễu theo lỗi / đã xét | Phân hoá cao (model) |','|---|---|---:|---:|---:|---:|']
 for x in ranking:lines.append(f'| {x["subject"]} | {x["code"]} | {x["key_disagreements_review"]} | {x["flags"]} | {x["distractor_identifiable"]}/{x["distractor_judged"]} | {x["high_count"]} |')
 if not ranking:lines.append('| Chưa có kết quả chấm hợp lệ | — | — | — | — | — |')
 lines+=['','Không coi phương án chỉ sai hoặc ngớ ngẩn là “theo lỗi thường gặp”. Tử số chỉ gồm lựa chọn được model gắn một lỗi cụ thể, mẫu số gồm lựa chọn đã phán đoán; chưa xác minh giữ riêng. Chi tiết từng phương án và từng ý TF ở '+str(ROOT/'audit/outputs/prototype-grades')+'; bảng theo môn ở '+str(ROOT/'audit/prototypes/SUMMARY.md')+'.','', '## Phân hoá trong đề thật','', 'Đây là phân tích chuỗi suy luận, không phải đo phân biệt từ điểm học sinh. Dùng chính thức làm mốc; đề tỉnh có thể khó hơn.']
 for s in profile_subjects:
  p=load(ROOT/'profiles'/s/'profile.compact.json');lines+=['','### '+s,'']
  for cls,prof in p['profiles_by_class'].items():
   lines.append('Bằng chứng: '+('chính thức' if cls=='official' else 'đề tỉnh')+'.')
   for move in prof.get('discrimination_moves',[])[:4]:lines.append('- '+str(move.get('move',''))+'; '+str(move.get('how_to_apply','')))
  stats=p['code_derived'];facts=stats.get('fact_use_counts',{});lines.append('Vai trò dữ kiện ghi nhớ: '+json.dumps(facts,ensure_ascii=False)+'. Đây là số hàng gắn nhãn, không trộn với tần suất theo đề.')
 lines+=['','## Mẫu ngoại ngữ mới','']
 for s,r in new.items():lines.append('- '+s+': '+r['status']+'; compile='+str(r.get('compile_ok'))+'; đã mở render='+str(r.get('visual_reviewed'))+'. Xem '+str(ROOT/'prototypes'/s/'NOTE.md'))
 lines+=['- Tiếng Trung: chờ chủ app cung cấp đề thật, không tạo mẫu.','', '## Giới hạn và các bước chưa đạt','', '- OCR ban đầu dùng Sol, sau sửa phân công dùng Luna; giữ provenance từng bản. Model EXTRACT phân tích mới: gpt-6.1-sol qua Codex subscription, một model/môn. Sol dùng cho suy luận, tự giải, audit và đề xuất. Không dùng khóa API tính phí. Context mới cùng model không phải kiểm chéo khác model hay giáo viên.', '- Dữ liệu cũ do các model khác phiên âm vẫn được giữ provenance. Không giả làm nguồn đã giáo viên kiểm. Lớp học, phân hoá, nhận diện lỗi nhiễu và tự giải đều có phần do model phán đoán.', '- Lỗi OCR, MathType/Word chuyển PDF, bảng/hình trống, ảnh thiếu nét và khóa lệch mã được giữ như khoảng chưa xác minh. Không tự dựng phần không đọc được.', '- Các nguồn là bản sao bên thứ ba/ảnh ứng viên; ảnh mạng xã hội tin cậy thấp. Tách bản tham khảo khỏi nội dung/tần suất và loại hoàn toàn đề app sinh khỏi bằng chứng.', '- Quét trùng mười từ và chữ số chỉ là kiểm phát hiện; không chứng minh không sao chép ý nghĩa. Các profile còn cảnh báo phải được rà trước khi đưa vào prompt product.', '- Không có kết quả học sinh để chứng minh độ phân biệt. Mẫu nhỏ, đặc biệt một đề chính thức, không đủ suy ra tần suất phổ quát.', '- Bước nào thất bại hai lần được lưu dưới outputs/stops; không đổi thiết kế để ép đạt. Chưa đạt không được viết thành số không hoặc đã kiểm.','']
 for p in stops:
  x=load(p);reason=x.get('reason') or '; '.join(x.get('errors',[]));lines.append('- '+str(p)+': '+str(reason)[:500])
 lines+=['','## Việc chủ app cần làm','','- Tìm đúng các trang/mã được liệt kê trong bảng, ưu tiên bản gốc rõ nét và khóa cùng mã.','- Quyết định các đề xuất ma trận, đặc biệt Toán đặt tay; chưa có thay đổi nào vào product.','- Nhờ giáo viên giải lại các bất đồng/cờ nội dung và duyệt mọi mẫu ngoại ngữ trước khi dùng.','', '## Tệp để xem lại','','- Prompts: '+str(ROOT/'audit/prompts'), '- Test cases: '+str(ROOT/'audit/test-cases.json'), '- Kiểm focused thực chạy: '+str(ROOT/'audit/outputs/data-checks.json'), '- Input và chọn mẫu: '+str(ROOT/'audit/outputs/stage1-manifest.json')+'; '+str(ROOT/'audit/outputs/selection.json'), '- Lệnh gọi, request, reply, model và lỗi thật: '+str(ROOT/'audit/outputs/calls'), '- Phiên âm, khóa, provenance và tình trạng: '+str(ROOT/'transcriptions'), '- Hồ sơ, rows và kiểm refs/copy: '+str(ROOT/'profiles'), '- Kết quả prototype: '+str(ROOT/'audit/outputs/prototype-results.json'), '- Nhật ký và commit: '+str(ROOT/'audit/RUNLOG.md'), '', 'Mở báo cáo bằng Finder hoặc chạy:', '```sh','open "'+str(ROOT/'audit/REPORT.md')+'"','```','']
 (ROOT/'audit/REPORT.md').write_text('\n'.join(lines),encoding='utf-8')
if __name__=='__main__':report()
